00096 SplitSeries Partitioner::getSplitSeries() const
00097 {
00098   SplitSeries splitSeries = 0;
00099   SplitSeries depth = 0;
00100 
00101   for( const auto &level : m_partStack )
00102   {
00103     if( level.split == CTU_LEVEL ) continue;
00104     else splitSeries += static_cast< SplitSeries >( level.split ) << ( depth * SPLIT_DMULT );
00105 
00106     depth++;
00107   }
00108 
00109   return splitSeries;
00110 }
00111 
00112 ModeTypeSeries Partitioner::getModeTypeSeries() const
00113 {
00114   ModeTypeSeries modeTypeSeries = 0;
00115   int depth = 0;
00116 
00117   for( const auto &level : m_partStack )
00118   {
00119     if( level.split == CTU_LEVEL ) continue;
00120     else modeTypeSeries += static_cast<int>(level.modeType) << (depth * 3);
00121 
00122     depth++;
00123   }
00124 
00125   return modeTypeSeries;
00126 }
