00168 // AdaptiveDepthPartitioner class
00170 
00171 void AdaptiveDepthPartitioner::setMaxMinDepth( unsigned& minDepth, unsigned& maxDepth, const CodingStructure& cs ) const
00172 {
00173   unsigned          stdMinDepth = 0;
00174   unsigned          stdMaxDepth = ( floorLog2(cs.sps->getCTUSize()) - floorLog2(cs.sps->getMinQTSize( cs.slice->getSliceType(), chType )));
00175   const Position    pos         = currArea().blocks[chType].pos();
00176   const unsigned    curSliceIdx = cs.slice->getIndependentSliceIdx();
00177   const unsigned    curTileIdx  = cs.pps->getTileIdx( currArea().lumaPos() );
00178 
00179   const CodingUnit* cuLeft        = cs.getCURestricted( pos.offset( -1,                               0 ), pos, curSliceIdx, curTileIdx, chType );
00180   const CodingUnit* cuBelowLeft   = cs.getCURestricted( pos.offset( -1, currArea().blocks[chType].height), pos, curSliceIdx, curTileIdx, chType );
00181   const CodingUnit* cuAbove       = cs.getCURestricted( pos.offset(  0,                              -1 ), pos, curSliceIdx, curTileIdx, chType );
00182   const CodingUnit* cuAboveRight  = cs.getCURestricted( pos.offset( currArea().blocks[chType].width, -1 ), pos, curSliceIdx, curTileIdx, chType );
00183 
00184   minDepth = stdMaxDepth;
00185   maxDepth = stdMinDepth;
00186 
00187   if( cuLeft )
00188   {
00189     minDepth = std::min<unsigned>( minDepth, cuLeft->qtDepth );
00190     maxDepth = std::max<unsigned>( maxDepth, cuLeft->qtDepth );
00191   }
00192   else
00193   {
00194     minDepth = stdMinDepth;
00195     maxDepth = stdMaxDepth;
00196   }
00197 
00198   if( cuBelowLeft )
00199   {
00200     minDepth = std::min<unsigned>( minDepth, cuBelowLeft->qtDepth );
00201     maxDepth = std::max<unsigned>( maxDepth, cuBelowLeft->qtDepth );
00202   }
00203   else
00204   {
00205     minDepth = stdMinDepth;
00206     maxDepth = stdMaxDepth;
00207   }
00208 
00209   if( cuAbove )
00210   {
00211     minDepth = std::min<unsigned>( minDepth, cuAbove->qtDepth );
00212     maxDepth = std::max<unsigned>( maxDepth, cuAbove->qtDepth );
00213   }
00214   else
00215   {
00216     minDepth = stdMinDepth;
00217     maxDepth = stdMaxDepth;
00218   }
00219 
00220   if( cuAboveRight )
00221   {
00222     minDepth = std::min<unsigned>( minDepth, cuAboveRight->qtDepth );
00223     maxDepth = std::max<unsigned>( maxDepth, cuAboveRight->qtDepth );
00224   }
00225   else
00226   {
00227     minDepth = stdMinDepth;
00228     maxDepth = stdMaxDepth;
00229   }
00230 
00231   minDepth = ( minDepth >= 1 ? minDepth - 1 : 0 );
00232   maxDepth = std::min<unsigned>( stdMaxDepth, maxDepth + 1 );
00233 }
