00249 void QTBTPartitioner::initCtu( const UnitArea& ctuArea, const ChannelType _chType, const Slice& slice )
00250 {
00251 #if _DEBUG
00252   m_currArea = ctuArea;
00253 #endif
00254   currDepth   = 0;
00255   currTrDepth = 0;
00256   currBtDepth = 0;
00257   currMtDepth = 0;
00258   currQtDepth = 0;
00259   currSubdiv  = 0;
00260   currQgPos   = ctuArea.lumaPos();
00261   currQgChromaPos = ctuArea.chromaFormat != CHROMA_400 ? ctuArea.chromaPos() : Position();
00262   currImplicitBtDepth = 0;
00263   chType      = _chType;
00264 
00265   m_partStack.clear();
00266   m_partStack.push_back( PartLevel( CTU_LEVEL, Partitioning{ ctuArea } ) );
00267   treeType = TREE_D;
00268   modeType = MODE_TYPE_ALL;
00269 }
00270 
00271 void QTBTPartitioner::splitCurrArea( const PartSplit split, const CodingStructure& cs )
00272 {
00273   CHECKD( !canSplit( split, cs ), "Trying to apply a prohibited split!" );
00274 
00275   bool isImplicit = isSplitImplicit( split, cs );
00276   bool canQtSplit = canSplit( CU_QUAD_SPLIT, cs );
00277   bool qgEnable = currQgEnable();
00278   bool qgChromaEnable = currQgChromaEnable();
00279 
00280   switch( split )
00281   {
00282   case CU_QUAD_SPLIT:
00283     m_partStack.push_back( PartLevel( split, PartitionerImpl::getCUSubPartitions( currArea(), cs ) ) );
00284     m_partStack.back().modeType = modeType;
00285     break;
00286   case CU_HORZ_SPLIT:
00287   case CU_VERT_SPLIT:
00288     m_partStack.push_back( PartLevel( split, PartitionerImpl::getCUSubPartitions( currArea(), cs, split ) ) );
00289     m_partStack.back().modeType = modeType;
00290     break;
00291   case CU_TRIH_SPLIT:
00292   case CU_TRIV_SPLIT:
00293     m_partStack.push_back( PartLevel( split, PartitionerImpl::getCUSubPartitions( currArea(), cs, split ) ) );
00294     m_partStack.back().modeType = modeType;
00295     break;
00296   case TU_MAX_TR_SPLIT:
00297     m_partStack.push_back( PartLevel( split, PartitionerImpl::getMaxTuTiling( currArea(), cs ) ) );
00298     break;
00299   case SBT_VER_HALF_POS0_SPLIT:
00300   case SBT_VER_HALF_POS1_SPLIT:
00301   case SBT_HOR_HALF_POS0_SPLIT:
00302   case SBT_HOR_HALF_POS1_SPLIT:
00303   case SBT_VER_QUAD_POS0_SPLIT:
00304   case SBT_VER_QUAD_POS1_SPLIT:
00305   case SBT_HOR_QUAD_POS0_SPLIT:
00306   case SBT_HOR_QUAD_POS1_SPLIT:
00307     m_partStack.push_back( PartLevel( split, PartitionerImpl::getSbtTuTiling( currArea(), cs, split ) ) );
00308     break;
00309   default:
00310     THROW( "Unknown split mode" );
00311     break;
00312   }
00313 
00314   currDepth++;
00315   currSubdiv++;
00316 #if _DEBUG
00317   m_currArea = m_partStack.back().parts.front();
00318 #endif
00319 
00320   if( split == TU_MAX_TR_SPLIT )
00321   {
00322     currTrDepth++;
00323   }
00324   else if( split >= SBT_VER_HALF_POS0_SPLIT && split <= SBT_HOR_QUAD_POS1_SPLIT )
00325   {
00326     currTrDepth++;
00327   }
00328   else
00329   {
00330     currTrDepth = 0;
00331   }
00332 
00333   if( split == CU_HORZ_SPLIT || split == CU_VERT_SPLIT || split == CU_TRIH_SPLIT || split == CU_TRIV_SPLIT )
00334   {
00335     currBtDepth++;
00336     if( isImplicit ) currImplicitBtDepth++;
00337     currMtDepth++;
00338 
00339     if( split == CU_TRIH_SPLIT || split == CU_TRIV_SPLIT )
00340     {
00341       // first and last part of triple split are equivalent to double bt split
00342       currBtDepth++;
00343       currSubdiv++;
00344     }
00345     m_partStack.back().canQtSplit = canQtSplit;
00346   }
00347   else if( split == CU_QUAD_SPLIT )
00348   {
00349     CHECK( currBtDepth > 0, "Cannot split a non-square area other than with a binary split" );
00350     CHECK( currMtDepth > 0, "Cannot split a non-square area other than with a binary split" );
00351     currMtDepth = 0;
00352     currBtDepth = 0;
00353     currQtDepth++;
00354     currSubdiv++;
00355   }
00356   qgEnable       &= (currSubdiv <= cs.slice->getCuQpDeltaSubdiv());
00357   qgChromaEnable &= (currSubdiv <= cs.slice->getCuChromaQpOffsetSubdiv());
00358   m_partStack.back().qgEnable       = qgEnable;
00359   m_partStack.back().qgChromaEnable = qgChromaEnable;
00360   if (qgEnable)
00361     currQgPos = currArea().lumaPos();
00362   if (qgChromaEnable)
00363     currQgChromaPos = currArea().chromaPos();
00364 }
00365 
00366 void QTBTPartitioner::canSplit( const CodingStructure &cs, bool& canNo, bool& canQt, bool& canBh, bool& canBv, bool& canTh, bool& canTv )
00367 {
00368   const PartSplit implicitSplit = m_partStack.back().checkdIfImplicit ? m_partStack.back().implicitSplit : getImplicitSplit( cs );
00369 
00370   const unsigned maxBTD         = cs.pcv->getMaxBtDepth( *cs.slice, chType ) + currImplicitBtDepth;
00371   const unsigned maxBtSize      = cs.pcv->getMaxBtSize ( *cs.slice, chType );
00372   const unsigned minBtSize      = cs.pcv->getMinBtSize ( *cs.slice, chType );
00373   const unsigned maxTtSize      = cs.pcv->getMaxTtSize ( *cs.slice, chType );
00374   const unsigned minTtSize      = cs.pcv->getMinTtSize ( *cs.slice, chType );
00375   const unsigned minQtSize      = cs.pcv->getMinQtSize ( *cs.slice, chType );
00376 
00377   canNo = canQt = canBh = canTh = canBv = canTv = true;
00378   bool canBtt = currMtDepth < maxBTD;
00379 
00380   // the minimal and maximal sizes are given in luma samples
00381   const CompArea&  area  = currArea().Y();
00382   const CompArea  *areaC = (chType == CHANNEL_TYPE_CHROMA) ? &(currArea().Cb()) : nullptr;
00383         PartLevel& level = m_partStack.back();
00384 
00385   const PartSplit lastSplit = level.split;
00386   const PartSplit parlSplit = lastSplit == CU_TRIH_SPLIT ? CU_HORZ_SPLIT : CU_VERT_SPLIT;
00387 
00388   // don't allow QT-splitting below a BT split
00389   if( lastSplit != CTU_LEVEL && lastSplit != CU_QUAD_SPLIT ) canQt = false;
00390   if( area.width <= minQtSize )                              canQt = false;
00391 
00392   if( areaC && areaC->width <= MIN_DUALTREE_CHROMA_WIDTH ) canQt = false;
00393   if( treeType == TREE_C )
00394   {
00395     canQt = canBh = canTh = canBv = canTv = false;
00396     return;
00397   }
00398   if( implicitSplit != CU_DONT_SPLIT )
00399   {
00400     canNo = canTh = canTv = false;
00401 
00402     canBh = implicitSplit == CU_HORZ_SPLIT;
00403     canBv = implicitSplit == CU_VERT_SPLIT;
00404     if (areaC && areaC->width == 4) canBv = false;
00405     if( !canBh && !canBv && !canQt ) canQt = true;
00406     return;
00407   }
00408 
00409   if( ( lastSplit == CU_TRIH_SPLIT || lastSplit == CU_TRIV_SPLIT ) && currPartIdx() == 1 )
00410   {
00411     canBh = parlSplit != CU_HORZ_SPLIT;
00412     canBv = parlSplit != CU_VERT_SPLIT;
00413   }
00414 
00415   if( canBtt && ( area.width <= minBtSize && area.height <= minBtSize )
00416       && ( ( area.width <= minTtSize && area.height <= minTtSize ) ) )
00417   {
00418     canBtt = false;
00419   }
00420   if( canBtt && ( area.width > maxBtSize || area.height > maxBtSize )
00421       && ( ( area.width > maxTtSize || area.height > maxTtSize ) ) )
00422   {
00423     canBtt = false;
00424   }
00425 
00426   if( !canBtt )
00427   {
00428     canBh = canTh = canBv = canTv = false;
00429 
00430     return;
00431   }
00432 
00433   if( area.width > maxBtSize || area.height > maxBtSize )
00434   {
00435     canBh = canBv = false;
00436   }
00437 
00438   // specific check for BT splits
00439   if( area.height <= minBtSize )                            canBh = false;
00440   if( area.width > MAX_TB_SIZEY && area.height <= MAX_TB_SIZEY ) canBh = false;
00441   if( areaC && areaC->width * areaC->height <= MIN_DUALTREE_CHROMA_SIZE )     canBh = false;
00442   if( area.width <= minBtSize )                              canBv = false;
00443   if( area.width <= MAX_TB_SIZEY && area.height > MAX_TB_SIZEY ) canBv = false;
00444   if (areaC && (areaC->width * areaC->height <= MIN_DUALTREE_CHROMA_SIZE || areaC->width == 4))     canBv = false;
00445   if( modeType == MODE_TYPE_INTER && area.width * area.height == 32 )  canBv = canBh = false;
00446   if( area.height <= 2 * minTtSize || area.height > maxTtSize || area.width > maxTtSize )
00447                                                                                        canTh = false;
00448   if( area.width > MAX_TB_SIZEY || area.height > MAX_TB_SIZEY )  canTh = false;
00449   if( areaC && areaC->width * areaC->height <= MIN_DUALTREE_CHROMA_SIZE*2 )     canTh = false;
00450   if( area.width <= 2 * minTtSize || area.width > maxTtSize || area.height > maxTtSize )
00451                                                                                        canTv = false;
00452   if( area.width > MAX_TB_SIZEY || area.height > MAX_TB_SIZEY )  canTv = false;
00453   if (areaC && (areaC->width * areaC->height <= MIN_DUALTREE_CHROMA_SIZE * 2 || areaC->width == 8))     canTv = false;
00454   if( modeType == MODE_TYPE_INTER && area.width * area.height == 64 )  canTv = canTh = false;
00455 
00456 }
00457 
00458 bool QTBTPartitioner::canSplit( const PartSplit split, const CodingStructure &cs )
00459 {
00460   const CompArea area       = currArea().Y();
00461   const unsigned maxTrSize  = cs.sps->getMaxTbSize();
00462 
00463   bool canNo, canQt, canBh, canTh, canBv, canTv;
00464 
00465   canSplit( cs, canNo, canQt, canBh, canBv, canTh, canTv );
00466   switch( split )
00467   {
00468   case CTU_LEVEL:
00469     THROW( "Checking if top level split is possible" );
00470     return true;
00471     break;
00472   case TU_MAX_TR_SPLIT:
00473     return area.width > maxTrSize || area.height > maxTrSize;
00474     break;
00475   case SBT_VER_HALF_POS0_SPLIT:
00476   case SBT_VER_HALF_POS1_SPLIT:
00477   case SBT_HOR_HALF_POS0_SPLIT:
00478   case SBT_HOR_HALF_POS1_SPLIT:
00479   case SBT_VER_QUAD_POS0_SPLIT:
00480   case SBT_VER_QUAD_POS1_SPLIT:
00481   case SBT_HOR_QUAD_POS0_SPLIT:
00482   case SBT_HOR_QUAD_POS1_SPLIT:
00483     return currTrDepth == 0;
00484     break;
00485   case CU_QUAD_SPLIT:
00486     return canQt;
00487   case CU_DONT_SPLIT:
00488     return canNo;
00489   case CU_HORZ_SPLIT:
00490     return canBh;
00491   case CU_VERT_SPLIT:
00492     return canBv;
00493   case CU_TRIH_SPLIT:
00494     return canTh;
00495   case CU_TRIV_SPLIT:
00496     return canTv;
00497   case CU_MT_SPLIT:
00498     return ( canBh || canTh || canBv || canTv );
00499   case CU_BT_SPLIT:
00500     return ( canBh || canBv );
00501   break;
00502   default:
00503     THROW( "Unknown split mode" );
00504     return false;
00505     break;
00506   }
00507 
00508   return true;
00509 }
00510 
00511 bool QTBTPartitioner::isSplitImplicit( const PartSplit split, const CodingStructure &cs )
00512 {
00513   return split == getImplicitSplit( cs );
00514 }
00515 
00516 PartSplit QTBTPartitioner::getImplicitSplit( const CodingStructure &cs )
00517 {
00518   if( m_partStack.back().checkdIfImplicit )
00519   {
00520     return m_partStack.back().implicitSplit;
00521   }
00522 
00523   PartSplit split = CU_DONT_SPLIT;
00524 
00525   if( split == CU_DONT_SPLIT )
00526   {
00527     const bool isBlInPic = cs.picture->Y().contains( currArea().Y().bottomLeft() );
00528     const bool isTrInPic = cs.picture->Y().contains( currArea().Y().topRight() );
00529 
00530     const CompArea& area      = currArea().Y();
00531     const unsigned maxBtSize  = cs.pcv->getMaxBtSize( *cs.slice, chType );
00532     const bool isBtAllowed    = area.width <= maxBtSize && area.height <= maxBtSize && currMtDepth < (cs.pcv->getMaxBtDepth(*cs.slice, chType) + currImplicitBtDepth);
00533     const unsigned minQtSize  = cs.pcv->getMinQtSize( *cs.slice, chType );
00534     const bool isQtAllowed    = area.width >  minQtSize && area.height >  minQtSize && currBtDepth == 0;
00535 
00536     if( !isBlInPic && !isTrInPic && isQtAllowed )
00537     {
00538       split = CU_QUAD_SPLIT;
00539     }
00540     else if( !isBlInPic && isBtAllowed && area.width <= MAX_TB_SIZEY )
00541     {
00542       split = CU_HORZ_SPLIT;
00543     }
00544     else if( !isTrInPic && isBtAllowed && area.height <= MAX_TB_SIZEY )
00545     {
00546       split = CU_VERT_SPLIT;
00547     }
00548     else if( !isBlInPic || !isTrInPic )
00549     {
00550       split = CU_QUAD_SPLIT;
00551     }
00552     if (CS::isDualITree(cs) && (currArea().Y().width > 64 || currArea().Y().height > 64))
00553     {
00554       split = CU_QUAD_SPLIT;
00555     }
00556     if( (!isBlInPic || !isTrInPic) && split == CU_DONT_SPLIT )
00557     {
00558       split = CU_QUAD_SPLIT;
00559     }
00560   }
00561 
00562   m_partStack.back().checkdIfImplicit = true;
00563   m_partStack.back().isImplicit = split != CU_DONT_SPLIT;
00564   m_partStack.back().implicitSplit = split;
00565 
00566   return split;
00567 }
00568 
00569 void QTBTPartitioner::exitCurrSplit()
00570 {
00571   PartSplit currSplit = m_partStack.back().split;
00572   unsigned  currIdx = m_partStack.back().idx;
00573 
00574   m_partStack.pop_back();
00575 
00576   CHECK( currDepth == 0, "depth is '0', although a split was performed" );
00577   currDepth--;
00578   currSubdiv--;
00579   if( currQgEnable() )
00580     currQgPos = currArea().lumaPos();
00581   if( currArea().chromaFormat != CHROMA_400 && currQgChromaEnable() )
00582     currQgChromaPos = currArea().chromaPos();
00583 #if _DEBUG
00584   m_currArea = m_partStack.back().parts[m_partStack.back().idx];
00585 #endif
00586 
00587   if( currSplit == CU_HORZ_SPLIT || currSplit == CU_VERT_SPLIT || currSplit == CU_TRIH_SPLIT || currSplit == CU_TRIV_SPLIT )
00588   {
00589     CHECK( !m_partStack.back().checkdIfImplicit, "Didn't check if the current split is implicit" );
00590     CHECK( currBtDepth == 0, "BT depth is '0', athough a BT split was performed" );
00591     CHECK( currMtDepth == 0, "MT depth is '0', athough a BT split was performed" );
00592     currMtDepth--;
00593     if( m_partStack.back().isImplicit ) currImplicitBtDepth--;
00594     currBtDepth--;
00595     if( ( currSplit == CU_TRIH_SPLIT || currSplit == CU_TRIV_SPLIT ) && currIdx != 1 )
00596     {
00597       CHECK( currBtDepth == 0, "BT depth is '0', athough a TT split was performed" );
00598       currBtDepth--;
00599       currSubdiv--;
00600     }
00601   }
00602   else if( currSplit == TU_MAX_TR_SPLIT )
00603   {
00604     CHECK( currTrDepth == 0, "TR depth is '0', although a TU split was performed" );
00605     currTrDepth--;
00606   }
00607   else if( currSplit >= SBT_VER_HALF_POS0_SPLIT && currSplit <= SBT_HOR_QUAD_POS1_SPLIT )
00608   {
00609     CHECK( currTrDepth == 0, "TR depth is '0', although a TU split was performed" );
00610     currTrDepth--;
00611   }
00612   else
00613   {
00614     CHECK( currTrDepth > 0, "RQT found with QTBT partitioner" );
00615 
00616     CHECK( currQtDepth == 0, "QT depth is '0', although a QT split was performed" );
00617     currQtDepth--;
00618     currSubdiv--;
00619   }
00620 }
00621 
00622 bool QTBTPartitioner::nextPart( const CodingStructure &cs, bool autoPop /*= false*/ )
00623 {
00624   const Position &prevPos = currArea().blocks[chType].pos();
00625 
00626   unsigned currIdx = ++m_partStack.back().idx;
00627 
00628   m_partStack.back().checkdIfImplicit = false;
00629   m_partStack.back().isImplicit = false;
00630 
00631   if( currIdx == 1 )
00632   {
00633     const CodingUnit* prevCU = cs.getCU( prevPos, chType );
00634     m_partStack.back().firstSubPartSplit = prevCU ? CU::getSplitAtDepth( *prevCU, currDepth ) : CU_DONT_SPLIT;
00635   }
00636 
00637   if( currIdx < m_partStack.back().parts.size() )
00638   {
00639     if( m_partStack.back().split == CU_TRIH_SPLIT || m_partStack.back().split == CU_TRIV_SPLIT )
00640     {
00641       // adapt the current bt depth
00642       if( currIdx == 1 ) currBtDepth--;
00643       else               currBtDepth++;
00644       if( currIdx == 1 ) currSubdiv--;
00645       else               currSubdiv++;
00646     }
00647   if( currQgEnable() )
00648     currQgPos = currArea().lumaPos();
00649   if( currQgChromaEnable() )
00650     currQgChromaPos = currArea().chromaPos();
00651 #if _DEBUG
00652     m_currArea = m_partStack.back().parts[currIdx];
00653 #endif
00654     return true;
00655   }
00656   else
00657   {
00658     if( autoPop ) exitCurrSplit();
00659     return false;
00660   }
00661 }
00662 
00663 bool QTBTPartitioner::hasNextPart()
00664 {
00665   return ( ( m_partStack.back().idx + 1 ) < m_partStack.back().parts.size() );
00666 }
00667 
00668 void TUIntraSubPartitioner::splitCurrArea( const PartSplit split, const CodingStructure& cs )
00669 {
00670   switch( split )
00671   {
00672     case TU_1D_HORZ_SPLIT:
00673     case TU_1D_VERT_SPLIT:
00674     {
00675       const UnitArea &area = currArea();
00676       m_partStack.push_back( PartLevel() );
00677       m_partStack.back().split = split;
00678       PartitionerImpl::getTUIntraSubPartitions( m_partStack.back().parts, area, cs, split );
00679       break;
00680     }
00681     case TU_MAX_TR_SPLIT: //we need this non ISP split because of the maxTrSize limitation
00682       m_partStack.push_back( PartLevel( split, PartitionerImpl::getMaxTuTiling( currArea(), cs ) ) );
00683       break;
00684     default:
00685       THROW( "Unknown ISP split mode" );
00686       break;
00687   }
00688 
00689   currDepth++;
00690   currTrDepth++; // we need this to identify the level. since the 1d partitions are forbidden if the RQT is on, there area no compatibility issues
00691 
00692 #if _DEBUG
00693   m_currArea = m_partStack.back().parts.front();
00694 #endif
00695 }
00696 
00697 void TUIntraSubPartitioner::exitCurrSplit()
00698 {
00699   PartSplit currSplit = m_partStack.back().split;
00700 
00701   m_partStack.pop_back();
00702 
00703   CHECK( currDepth == 0, "depth is '0', although a split was performed" );
00704 
00705   currDepth--;
00706   currTrDepth--;
00707 
00708 #if _DEBUG
00709   m_currArea = m_partStack.back().parts[m_partStack.back().idx];
00710 #endif
00711 
00712   CHECK( !( currSplit == TU_1D_HORZ_SPLIT || currSplit == TU_1D_VERT_SPLIT || currSplit == TU_MAX_TR_SPLIT ), "Unknown 1D partition split type!" );
00713 }
00714 
00715 bool TUIntraSubPartitioner::nextPart( const CodingStructure &cs, bool autoPop /*= false*/ )
00716 {
00717   unsigned currIdx = ++m_partStack.back().idx;
00718 
00719   m_partStack.back().checkdIfImplicit = false;
00720   m_partStack.back().isImplicit = false;
00721 
00722   if( currIdx < m_partStack.back().parts.size() )
00723   {
00724 #if _DEBUG
00725     m_currArea = m_partStack.back().parts[m_partStack.back().idx];
00726 #endif
00727     return true;
00728   }
00729   else
00730   {
00731     if( autoPop ) exitCurrSplit();
00732     return false;
00733   }
00734 }
00735 
00736 bool TUIntraSubPartitioner::hasNextPart()
00737 {
00738   return ( ( m_partStack.back().idx + 1 ) < m_partStack.back().parts.size() );
00739 }
00740 
00741 bool TUIntraSubPartitioner::canSplit( const PartSplit split, const CodingStructure &cs )
00742 {
00743   //const PartSplit implicitSplit = getImplicitSplit(cs);
00744   const UnitArea &area = currArea();
00745 
00746   switch( split )
00747   {
00748     case TU_1D_HORZ_SPLIT:
00749     {
00750       return area.lheight() == m_partStack[0].parts[0].lheight();
00751     }
00752     case TU_1D_VERT_SPLIT:
00753     {
00754       return area.lwidth() == m_partStack[0].parts[0].lwidth();
00755     }
00756     case TU_MAX_TR_SPLIT:
00757     {
00758       //this split is performed implicitly with the other splits
00759       return false;
00760     }
00761     default:
00762       THROW( "Unknown 1-D split mode" );
00763       break;
00764   }
00765 }
00766 
00768 // Partitioner methods describing the actual partitioning logic
00770 
00771 Partitioning PartitionerImpl::getCUSubPartitions( const UnitArea &cuArea, const CodingStructure &cs, const PartSplit _splitType /*= CU_QUAD_SPLIT*/ )
00772 {
00773   const PartSplit splitType = _splitType;
00774 
00775   if( splitType == CU_QUAD_SPLIT )
00776   {
00777     if( !cs.pcv->noChroma2x2 )
00778     {
00779       Partitioning sub;
00780 
00781       sub.resize( 4, cuArea );
00782 
00783       for( uint32_t i = 0; i < 4; i++ )
00784       {
00785         for( auto &blk : sub[i].blocks )
00786         {
00787           blk.height >>= 1;
00788           blk.width  >>= 1;
00789           if( i >= 2 ) blk.y += blk.height;
00790           if( i &  1 ) blk.x += blk.width;
00791         }
00792 
00793         CHECK( sub[i].lumaSize().height < MIN_TB_SIZEY, "the split causes the block to be smaller than the minimal TU size" );
00794       }
00795 
00796       return sub;
00797     }
00798     else
00799     {
00800       const uint32_t minCUSize = 1 << cs.sps->getLog2MinCodingBlockSize();
00801 
00802       bool canSplit = cuArea.lumaSize().width > minCUSize && cuArea.lumaSize().height > minCUSize;
00803 
00804       Partitioning ret;
00805 
00806 
00807       if( canSplit )
00808       {
00809         ret.resize( 4 );
00810 
00811         if( cuArea.chromaFormat == CHROMA_400 )
00812         {
00813           CompArea  blkY = cuArea.Y();
00814           blkY.width >>= 1;
00815           blkY.height >>= 1;
00816           ret[0]  = UnitArea( cuArea.chromaFormat, blkY );
00817           blkY.x += blkY.width;
00818           ret[1]  = UnitArea( cuArea.chromaFormat, blkY );
00819           blkY.x -= blkY.width;
00820           blkY.y += blkY.height;
00821           ret[2]  = UnitArea( cuArea.chromaFormat, blkY );
00822           blkY.x += blkY.width;
00823           ret[3]  = UnitArea( cuArea.chromaFormat, blkY );
00824         }
00825         else
00826         {
00827           for( uint32_t i = 0; i < 4; i++ )
00828           {
00829             ret[i] = cuArea;
00830 
00831             CompArea &blkY  = ret[i].Y();
00832             CompArea &blkCb = ret[i].Cb();
00833             CompArea &blkCr = ret[i].Cr();
00834 
00835             blkY.width  /= 2;
00836             blkY.height /= 2;
00837 
00838             // TODO: get those params from SPS
00839             if( blkCb.width > 4 )
00840             {
00841               blkCb.width  /= 2;
00842               blkCb.height /= 2;
00843               blkCr.width  /= 2;
00844               blkCr.height /= 2;
00845             }
00846             else if( i > 0 )
00847             {
00848               blkCb = CompArea();
00849               blkCr = CompArea();
00850             }
00851 
00852             if( ( i & 1 ) == 1 )
00853             {
00854               blkY.x  += blkY .width;
00855               blkCb.x += blkCb.width;
00856               blkCr.x += blkCr.width;
00857             }
00858 
00859             if( i > 1 )
00860             {
00861               blkY.y  += blkY .height;
00862               blkCb.y += blkCb.height;
00863               blkCr.y += blkCr.height;
00864             }
00865           }
00866         }
00867       }
00868 
00869       return ret;
00870     }
00871   }
00872   else if( splitType == CU_HORZ_SPLIT )
00873   {
00874     Partitioning sub;
00875 
00876     sub.resize(2, cuArea);
00877 
00878     for (uint32_t i = 0; i < 2; i++)
00879     {
00880       for (auto &blk : sub[i].blocks)
00881       {
00882         blk.height >>= 1;
00883         if (i == 1) blk.y += blk.height;
00884       }
00885 
00886       CHECK(sub[i].lumaSize().height < MIN_TB_SIZEY, "the cs split causes the block to be smaller than the minimal TU size");
00887     }
00888 
00889     return sub;
00890   }
00891   else if( splitType == CU_VERT_SPLIT )
00892   {
00893     Partitioning sub;
00894 
00895     sub.resize( 2, cuArea );
00896 
00897     for( uint32_t i = 0; i < 2; i++ )
00898     {
00899       for( auto &blk : sub[i].blocks )
00900       {
00901         blk.width >>= 1;
00902         if( i == 1 ) blk.x += blk.width;
00903       }
00904 
00905       CHECK( sub[i].lumaSize().width < MIN_TB_SIZEY, "the split causes the block to be smaller than the minimal TU size" );
00906     }
00907 
00908     return sub;
00909   }
00910   else if( splitType == CU_TRIH_SPLIT )
00911   {
00912     Partitioning sub;
00913 
00914     sub.resize( 3, cuArea );
00915 
00916     for( int i = 0; i < 3; i++ )
00917     {
00918       for( auto &blk : sub[i].blocks )
00919       {
00920         blk.height >>= 1;
00921         if( ( i + 1 ) & 1 ) blk.height >>= 1;
00922         if( i == 1 )        blk.y       +=     blk.height / 2;
00923         if( i == 2 )        blk.y       += 3 * blk.height;
00924       }
00925 
00926       CHECK( sub[i].lumaSize().height < MIN_TB_SIZEY, "the cs split causes the block to be smaller than the minimal TU size" );
00927     }
00928 
00929     return sub;
00930   }
00931   else if( splitType == CU_TRIV_SPLIT )
00932   {
00933     Partitioning sub;
00934 
00935     sub.resize( 3, cuArea );
00936 
00937     for( int i = 0; i < 3; i++ )
00938     {
00939       for( auto &blk : sub[i].blocks )
00940       {
00941         blk.width >>= 1;
00942 
00943         if( ( i + 1 ) & 1 ) blk.width >>= 1;
00944         if( i == 1 )        blk.x      +=     blk.width / 2;
00945         if( i == 2 )        blk.x      += 3 * blk.width;
00946       }
00947 
00948       CHECK( sub[i].lumaSize().width < MIN_TB_SIZEY, "the cs split causes the block to be smaller than the minimal TU size" );
00949     }
00950 
00951     return sub;
00952   }
00953   else
00954   {
00955     THROW( "Unknown CU sub-partitioning" );
00956     return Partitioning();
00957   }
00958 }
00959 
00960 void PartitionerImpl::getTUIntraSubPartitions( Partitioning &sub, const UnitArea &tuArea, const CodingStructure &cs, const PartSplit splitType )
00961 {
00962   uint32_t nPartitions;
00963   uint32_t splitDimensionSize = CU::getISPSplitDim( tuArea.lumaSize().width, tuArea.lumaSize().height, splitType );
00964 
00965   bool isDualTree = CS::isDualITree( cs ) || cs.treeType != TREE_D;
00966 
00967   if( splitType == TU_1D_HORZ_SPLIT )
00968   {
00969     nPartitions = tuArea.lumaSize().height >> floorLog2(splitDimensionSize);
00970 
00971     sub.resize( nPartitions );
00972 
00973     for( uint32_t i = 0; i < nPartitions; i++ )
00974     {
00975       sub[i] = tuArea;
00976       CompArea& blkY = sub[i].blocks[COMPONENT_Y];
00977 
00978       blkY.height = splitDimensionSize;
00979       blkY.y = i > 0 ? sub[i - 1].blocks[COMPONENT_Y].y + splitDimensionSize : blkY.y;
00980 
00981       CHECK( sub[i].lumaSize().height < 1, "the cs split causes the block to be smaller than the minimal TU size" );
00982     }
00983   }
00984   else if( splitType == TU_1D_VERT_SPLIT )
00985   {
00986     nPartitions = tuArea.lumaSize().width >> floorLog2(splitDimensionSize);
00987 
00988     sub.resize( nPartitions );
00989 
00990     for( uint32_t i = 0; i < nPartitions; i++ )
00991     {
00992       sub[i] = tuArea;
00993       CompArea& blkY = sub[i].blocks[COMPONENT_Y];
00994 
00995       blkY.width = splitDimensionSize;
00996       blkY.x = i > 0 ? sub[i - 1].blocks[COMPONENT_Y].x + splitDimensionSize : blkY.x;
00997       CHECK( sub[i].lumaSize().width < 1, "the split causes the block to be smaller than the minimal TU size" );
00998     }
00999   }
01000   else
01001   {
01002     THROW( "Unknown TU sub-partitioning" );
01003   }
01004   //we only partition luma, so there is going to be only one chroma tu at the end (unless it is dual tree, in which case there won't be any chroma components)
01005   uint32_t partitionsWithoutChroma = (cs.area.chromaFormat == CHROMA_400) ? 0 : (isDualTree ? nPartitions : nPartitions - 1);
01006   for( uint32_t i = 0; i < partitionsWithoutChroma; i++ )
01007   {
01008     CompArea& blkCb = sub[i].blocks[COMPONENT_Cb];
01009     CompArea& blkCr = sub[i].blocks[COMPONENT_Cr];
01010     blkCb = CompArea();
01011     blkCr = CompArea();
01012   }
01013 }
01014 
01015 static const int g_maxRtGridSize = 3;
01016 
01017 static const int g_zScanToX[1 << ( g_maxRtGridSize << 1 )] =
01018 {
01019    0,  1,  0,  1,  2,  3,  2,  3,
01020    0,  1,  0,  1,  2,  3,  2,  3,
01021    4,  5,  4,  5,  6,  7,  6,  7,
01022    4,  5,  4,  5,  6,  7,  6,  7,
01023    0,  1,  0,  1,  2,  3,  2,  3,
01024    0,  1,  0,  1,  2,  3,  2,  3,
01025    4,  5,  4,  5,  6,  7,  6,  7,
01026    4,  5,  4,  5,  6,  7,  6,  7,
01027 };
01028 static const int g_zScanToY[1 << ( g_maxRtGridSize << 1 )] =
01029 {
01030    0,  0,  1,  1,  0,  0,  1,  1,
01031    2,  2,  3,  3,  2,  2,  3,  3,
01032    0,  0,  1,  1,  0,  0,  1,  1,
01033    2,  2,  3,  3,  2,  2,  3,  3,
01034    4,  4,  5,  5,  4,  4,  5,  5,
01035    6,  6,  7,  7,  6,  6,  7,  7,
01036    4,  4,  5,  5,  4,  4,  5,  5,
01037    6,  6,  7,  7,  6,  6,  7,  7,
01038 };
01039 static const int g_rsScanToZ[1 << ( g_maxRtGridSize << 1 )] =
01040 {
01041    0,  1,  4,  5, 16, 17, 20, 21,
01042    2,  3,  6,  7, 18, 19, 22, 23,
01043    8,  9, 12, 13, 24, 25, 28, 29,
01044   10, 11, 14, 15, 26, 27, 30, 31,
01045   32, 33, 36, 37, 48, 49, 52, 53,
01046   34, 35, 38, 39, 50, 51, 54, 55,
01047   40, 41, 44, 45, 56, 57, 60, 61,
01048   42, 43, 46, 47, 58, 59, 62, 63,
01049 };
01050 
01051 Partitioning PartitionerImpl::getMaxTuTiling( const UnitArea &cuArea, const CodingStructure &cs )
01052 {
01053   static_assert( MAX_LOG2_DIFF_CU_TR_SIZE <= g_maxRtGridSize, "Z-scan tables are only provided for MAX_LOG2_DIFF_CU_TR_SIZE for up to 3 (8x8 tiling)!" );
01054 
01055   const Size area     = cuArea.lumaSize();
01056   const int maxTrSize = (area.width>64 || area.height>64) ? 64 : cs.sps->getMaxTbSize();
01057   const int numTilesH = std::max<int>( 1, area.width  / maxTrSize );
01058   const int numTilesV = std::max<int>( 1, area.height / maxTrSize );
01059   const int numTiles  = numTilesH * numTilesV;
01060 
01061   CHECK( numTiles > MAX_CU_TILING_PARTITIONS, "CU partitioning requires more partitions than available" );
01062 
01063   Partitioning ret;
01064   ret.resize( numTiles, cuArea );
01065 
01066   for( int i = 0; i < numTiles; i++ )
01067   {
01068     const int rsy = i / numTilesH;
01069     const int rsx = i % numTilesH;
01070 
01071     const int x = g_zScanToX[g_rsScanToZ[( rsy << g_maxRtGridSize ) + rsx]];
01072     const int y = g_zScanToY[g_rsScanToZ[( rsy << g_maxRtGridSize ) + rsx]];
01073 
01074     UnitArea& tile = ret[i];
01075 
01076     for( CompArea &comp : tile.blocks )
01077     {
01078       if( !comp.valid() ) continue;
01079 
01080       comp.width  /= numTilesH;
01081       comp.height /= numTilesV;
01082 
01083       comp.x += comp.width  * x;
01084       comp.y += comp.height * y;
01085     }
01086   }
01087 
01088   return ret;
01089 }
01090 
01091 Partitioning PartitionerImpl::getSbtTuTiling( const UnitArea& cuArea, const CodingStructure &cs, const PartSplit splitType )
01092 {
01093   Partitioning ret;
01094   int numTiles = 2;
01095   int widthFactor, heightFactor, xOffsetFactor, yOffsetFactor; // y = (x * factor) >> 2;
01096   assert( splitType >= SBT_VER_HALF_POS0_SPLIT && splitType <= SBT_HOR_QUAD_POS1_SPLIT );
01097 
01098   ret.resize( numTiles, cuArea );
01099   for( int i = 0; i < numTiles; i++ )
01100   {
01101     if( splitType >= SBT_VER_QUAD_POS0_SPLIT )
01102     {
01103       if( splitType == SBT_HOR_QUAD_POS0_SPLIT || splitType == SBT_HOR_QUAD_POS1_SPLIT )
01104       {
01105         widthFactor = 4;
01106         xOffsetFactor = 0;
01107         heightFactor = ( ( i == 0 && splitType == SBT_HOR_QUAD_POS0_SPLIT ) || ( i == 1 && splitType == SBT_HOR_QUAD_POS1_SPLIT ) ) ? 1 : 3;
01108         yOffsetFactor = ( i == 0 ) ? 0 : ( splitType == SBT_HOR_QUAD_POS0_SPLIT ? 1 : 3 );
01109       }
01110       else
01111       {
01112         widthFactor = ( ( i == 0 && splitType == SBT_VER_QUAD_POS0_SPLIT ) || ( i == 1 && splitType == SBT_VER_QUAD_POS1_SPLIT ) ) ? 1 : 3;
01113         xOffsetFactor = ( i == 0 ) ? 0 : ( splitType == SBT_VER_QUAD_POS0_SPLIT ? 1 : 3 );
01114         heightFactor = 4;
01115         yOffsetFactor = 0;
01116       }
01117     }
01118     else
01119     {
01120       if( splitType == SBT_HOR_HALF_POS0_SPLIT || splitType == SBT_HOR_HALF_POS1_SPLIT )
01121       {
01122         widthFactor = 4;
01123         xOffsetFactor = 0;
01124         heightFactor = 2;
01125         yOffsetFactor = ( i == 0 ) ? 0 : 2;
01126       }
01127       else
01128       {
01129         widthFactor = 2;
01130         xOffsetFactor = ( i == 0 ) ? 0 : 2;
01131         heightFactor = 4;
01132         yOffsetFactor = 0;
01133       }
01134     }
01135 
01136     UnitArea& tile = ret[i];
01137     for( CompArea &comp : tile.blocks )
01138     {
01139       if( !comp.valid() ) continue;
01140       comp.x += ( comp.width  * xOffsetFactor ) >> 2;
01141       comp.y += ( comp.height * yOffsetFactor ) >> 2;
01142       comp.width = ( comp.width  * widthFactor ) >> 2;
01143       comp.height = ( comp.height * heightFactor ) >> 2;
01144     }
01145   }
01146 
01147   return ret;
01148 }
